import{c as t,Q as d,j as o,m as a}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/env-vars.md","filePath":"reference/env-vars.md"}'),c={name:"reference/env-vars.md"};function r(n,e,i,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Reference list of every environment variable read by the Phlix Media Server, its default, and a one-line description. Each entry links back to the file that consumes it.</p><h2 id="container-bootstrap" tabindex="-1">Container &amp; bootstrap <a class="header-anchor" href="#container-bootstrap" aria-label="Permalink to &quot;Container &amp; bootstrap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_CONTAINER_COMPILE</code></td><td><em>unset</em></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) enables PHP-DI&#39;s compiled-container cache in <code>var/cache/container/</code>. Disabled by default for dev parity. See <code>Phlix\\Common\\Container\\ContainerFactory</code>.</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_DEBUG_EVENTS</code></td><td><code>0</code></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) wraps the PSR-14 dispatcher in Tukio&#39;s <code>DebugEventDispatcher</code>, which logs every dispatched event class at debug level on the <code>events</code> channel (<code>.logs/events.log</code>). Useful for tracing plugin behaviour; leave off in production. See <code>Phlix\\Common\\Events\\EventDispatcherFactory</code> and <code>docs/dev/event-reference.md</code>.</td></tr></tbody></table><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_PLUGINS_ALLOW_HTTP</code></td><td><code>0</code></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) lets the plugin loader accept plain <code>http://</code> source URLs. Default off — HTTPS or <code>file://</code> only. See <code>Phlix\\Plugins\\Installer\\HttpInstaller</code>.</td></tr><tr><td><code>PHLIX_PLUGINS_REQUIRE_SIGNATURE</code></td><td><code>0</code></td><td>When truthy, the plugin loader refuses to install unsigned plugins and refuses signatures missing from the trusted-key allowlist. Default off, which means unsigned plugins install with a warning on the <code>plugins</code> log channel. See <code>Phlix\\Plugins\\Signature\\SignatureVerifier</code>.</td></tr><tr><td><code>PHLIX_PLUGINS_COMPOSER_TIMEOUT</code></td><td><code>120</code></td><td>Hard timeout (seconds) on the per-plugin <code>composer install --no-dev</code> subprocess. See <code>Phlix\\Plugins\\Installer\\ComposerRunner</code>.</td></tr></tbody></table><h2 id="auth" tabindex="-1">Auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;Auth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>JWT_SECRET</code></td><td><code>default-secret-change-me</code></td><td>HMAC secret used to sign / verify JWT access and refresh tokens. The default is intentionally insecure so a missing env var fails closed in production deployments. Read by <code>Phlix\\Common\\Container\\Providers\\AuthServicesProvider</code>.</td></tr></tbody></table><h2 id="hub-pairing" tabindex="-1">Hub / Pairing <a class="header-anchor" href="#hub-pairing" aria-label="Permalink to &quot;Hub / Pairing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_HUB_URL</code></td><td><em>unset</em></td><td>Base URL of the Phlix Hub to pair with (e.g. <code>https://hub.example.com</code>). When set, the server initiates pairing automatically on startup if enrolled. See <code>Phlix\\Hub\\HubClient</code> and <code>config/hub.php</code>.</td></tr><tr><td><code>PHLIX_HUB_JWKS_URL</code></td><td><em>unset</em></td><td>URL of the hub&#39;s JWKS endpoint for validating hub-issued JWTs. Typically set automatically during enrollment. See <code>Phlix\\Hub\\HubJwtValidator</code> and <code>config/hub.php</code>.</td></tr><tr><td><code>PHLIX_HUB_ENROLLMENT_TOKEN</code></td><td><em>unset</em></td><td>When set, overrides the enrollment token read from <code>config/hub-enrollment.json</code>. Mostly useful for automation / container orchestration. See <code>Phlix\\Hub\\HubClient::loadEnrollment()</code>.</td></tr><tr><td><code>PHLIX_HUB_HEARTBEAT_INTERVAL</code></td><td><code>60</code></td><td>Interval in seconds between hub heartbeat calls. Must be between 30 and 3600. See <code>Phlix\\Hub\\HubClient::startHeartbeatLoop()</code> and <code>config/hub.php</code>.</td></tr><tr><td><code>PHLIX_SUBDOMAIN_AUTO_CLAIM</code></td><td><code>1</code></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) automatically claims a *.phlix.media subdomain from the hub after enrollment. See <code>Phlix\\Hub\\SubdomainClient</code> and <code>config/hub.php</code>.</td></tr><tr><td><code>PHLIX_TLS_ENABLED</code></td><td><code>1</code></td><td>When truthy enables TLS/HTTPS for the server&#39;s public hostname. Requires a subdomain to be allocated. See <code>config/hub.php</code>.</td></tr><tr><td><code>PHLIX_DOMAIN</code></td><td><code>phlix.media</code></td><td>The base domain for server subdomains (e.g. <code>abc12345.phlix.media</code>). See <code>config/hub.php</code>.</td></tr></tbody></table><h2 id="relay-tunnel" tabindex="-1">Relay tunnel <a class="header-anchor" href="#relay-tunnel" aria-label="Permalink to &quot;Relay tunnel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_RELAY_ENABLED</code></td><td><code>0</code></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) enables the persistent WSS relay tunnel to the hub. Requires the server to be enrolled. See <code>Phlix\\Hub\\RelayConfig</code> and <code>config/relay.php</code>.</td></tr><tr><td><code>PHLIX_RELAY_HUB_URL</code></td><td><code>wss://hub.example.com/api/v1/servers/{id}/relay</code></td><td>WebSocket URL of the hub relay endpoint. <code>{id}</code> is replaced with the server&#39;s UUID from enrollment. See <code>Phlix\\Hub\\RelayConsumer</code> and <code>config/relay.php</code>.</td></tr><tr><td><code>PHLIX_RELAY_TUNNEL_HOSTNAME</code></td><td><em>empty</em></td><td>Public hostname assigned to this server&#39;s relay tunnel (e.g. <code>my-server.phlix.media</code>). See <code>Phlix\\Hub\\RelayConfig</code> and <code>config/relay.php</code>.</td></tr><tr><td><code>PHLIX_RELAY_RECONNECT_DELAY</code></td><td><code>5</code></td><td>Seconds to wait before attempting to reconnect after the relay tunnel is disconnected. See <code>Phlix\\Hub\\RelayConfig</code> and <code>config/relay.php</code>.</td></tr><tr><td><code>PHLIX_RELAY_PING_INTERVAL</code></td><td><code>30</code></td><td>Seconds between keep-alive ping frames sent over the relay tunnel. See <code>Phlix\\Hub\\RelayConfig</code> and <code>config/relay.php</code>.</td></tr><tr><td><code>PHLIX_RELAY_PING_TIMEOUT</code></td><td><code>10</code></td><td>Seconds to wait for a pong response before considering the relay connection dead. See <code>Phlix\\Hub\\RelayConfig</code> and <code>config/relay.php</code>.</td></tr></tbody></table><h2 id="port-forwarding-remote-access" tabindex="-1">Port forwarding / remote access <a class="header-anchor" href="#port-forwarding-remote-access" aria-label="Permalink to &quot;Port forwarding / remote access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_PORT_FORWARD_AUTO</code></td><td><code>1</code></td><td>When truthy (<code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code>) enables automatic port forwarding via UPnP-IGD on startup. See <code>Phlix\\Network\\PortForwardService</code> and <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_EXTERNAL_PORT</code></td><td><code>32400</code></td><td>Port to use for automatic port forwarding. Both external and internal ports use this value by default. See <code>Phlix\\Network\\PortForwardService</code> and <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_EXTERNAL_HTTP_PORT</code></td><td><code>8080</code></td><td>External HTTP port for the web portal when accessed remotely. See <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_EXTERNAL_HTTPS_PORT</code></td><td><code>8443</code></td><td>External HTTPS port for the web portal when accessed remotely. See <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_UPNP_ENABLED</code></td><td><code>1</code></td><td>When truthy enables UPnP-IGD port mapping attempts. When falsy, only STUN-based external IP detection is used. See <code>Phlix\\Network\\UpnpIgdClient</code> and <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_STUN_SERVER</code></td><td><code>stun.l.google.com</code></td><td>STUN server hostname for discovering the server&#39;s public IP address. See <code>Phlix\\Network\\StunClient</code> and <code>config/port-forward.php</code>.</td></tr><tr><td><code>PHLIX_STUN_PORT</code></td><td><code>19302</code></td><td>STUN server port. See <code>Phlix\\Network\\StunClient</code> and <code>config/port-forward.php</code>.</td></tr></tbody></table><h2 id="database-test-only" tabindex="-1">Database (test only) <a class="header-anchor" href="#database-test-only" aria-label="Permalink to &quot;Database (test only)&quot;">​</a></h2><p>These are consumed by <code>phpunit.xml</code> only and have no effect on production.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>APP_ENV</code></td><td><code>testing</code></td><td>Marks the runtime as a test environment.</td></tr><tr><td><code>DB_HOST</code></td><td><code>127.0.0.1</code></td><td>MySQL host used by integration tests.</td></tr><tr><td><code>DB_PORT</code></td><td><code>3306</code></td><td>MySQL port used by integration tests.</td></tr><tr><td><code>DB_DATABASE</code></td><td><code>phlix_test</code></td><td>MySQL database name used by integration tests.</td></tr><tr><td><code>DB_USER</code></td><td><code>root</code></td><td>MySQL username used by integration tests.</td></tr><tr><td><code>DB_PASSWORD</code></td><td><em>empty</em></td><td>MySQL password used by integration tests.</td></tr></tbody></table><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_HTTP_PORT</code></td><td><code>32400</code></td><td>HTTP port the server listens on. Overridden by <code>config/server.php</code> <code>server.port</code> at runtime. See <code>config/server.php</code>.</td></tr><tr><td><code>PHLIX_PUBLIC_URL</code></td><td><em>unset</em></td><td>Public URL used in Hub relay and DLNA announcements. Must be set if the server is behind a reverse proxy. See <code>Phlix\\Server\\Core\\Application</code>.</td></tr><tr><td><code>PHLIX_LOG_LEVEL</code></td><td><code>info</code></td><td>Minimum log level for application logs written to <code>.logs/app.log</code>. Valid values (in order of verbosity): <code>debug</code>, <code>info</code>, <code>notice</code>, <code>warning</code>, <code>error</code>, <code>critical</code>, <code>alert</code>, <code>emergency</code>. See <code>config/logger.php</code>.</td></tr></tbody></table><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_DATABASE_HOST</code></td><td><code>127.0.0.1</code></td><td>MySQL host; maps to <code>config/database.php</code> <code>connections.mysql.host</code>.</td></tr><tr><td><code>PHLIX_DATABASE_PORT</code></td><td><code>3306</code></td><td>MySQL port; maps to <code>config/database.php</code> <code>connections.mysql.port</code>.</td></tr><tr><td><code>PHLIX_DATABASE_NAME</code></td><td><code>phlix</code></td><td>Database name; maps to <code>config/database.php</code> <code>connections.mysql.database</code>.</td></tr><tr><td><code>PHLIX_DATABASE_USER</code></td><td><code>phlix</code></td><td>Database username; maps to <code>config/database.php</code> <code>connections.mysql.username</code>.</td></tr><tr><td><code>PHLIX_DATABASE_PASSWORD</code></td><td><em>empty</em></td><td>Database password. Alias for the <code>DB_PASSWORD</code> env var consumed by <code>config/database.php</code>. Prefer setting <code>DB_PASSWORD</code> to avoid confusion.</td></tr></tbody></table><h2 id="transcoding-hardware-acceleration" tabindex="-1">Transcoding / Hardware acceleration <a class="header-anchor" href="#transcoding-hardware-acceleration" aria-label="Permalink to &quot;Transcoding / Hardware acceleration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PHLIX_HWACCEL</code></td><td><code>none</code></td><td>Preferred hardware acceleration. Valid values: <code>nvidia</code>, <code>vaapi</code>, <code>videotoolbox</code>, <code>qsv</code>, <code>amf</code>, <code>v4l2</code>, <code>none</code>. Overridden by <code>config/ffmpeg.php</code> <code>hwaccel.vendor_priority</code>. See <code>config/ffmpeg.php</code>.</td></tr></tbody></table><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>TZ</code></td><td>system TZ</td><td>PHP <code>date_default_timezone_set()</code> value. Controls timestamps in logs and EPG data. Set to your local timezone (e.g., <code>America/New_York</code>, <code>Europe/London</code>).</td></tr></tbody></table><blockquote><p>The production database credentials live in <code>config/database.php</code> (which reads <code>DB_PASSWORD</code> from the environment via <code>getenv(&#39;DB_PASSWORD&#39;)</code>).</p></blockquote>',28)])])}const p=t(c,[["render",r]]);export{u as __pageData,p as default};
